program='''from collections import Counter

def transform(grid):
    blocks = []
    for br in range(5):
        for bc in range(5):
            r0, c0 = 6 * br, 6 * bc
            blocks.append([[grid[r0+r][c0+c] for c in range(5)] for r in range(5)])
    tile = [[Counter(block[r][c] for block in blocks).most_common(1)[0][0]
             for c in range(5)] for r in range(5)]
    damaged = min(blocks, key=lambda b: sum(x != 8 for row in b for x in row))
    removed = [(r, c, tile[r][c]) for r in range(5) for c in range(5)
               if damaged[r][c] == 8 and tile[r][c] != 8]
    if any(color == 4 for r, c, color in removed):
        for r in range(5):
            for c in range(5):
                if tile[r][c] in (0, 2):
                    tile[r][c] = 1
    elif any(2 in row for row in tile):
        for r in range(5):
            for c in range(5):
                if tile[r][c] == 0 or (tile[r][c] == 2 and (r, c) != (0, 3)):
                    tile[r][c] = 1
    else:
        for r, c, color in removed:
            if color != 4:
                tile[r][c] = 1
    return tile
'''
